def load_bounds(*weights):
    if not weights:            # empty truck: nothing to aggregate
        return (0, 0)
    return (min(weights), max(weights))

def flatten_nested(items, depth):
    if depth <= 0:
        return list(items)          # budget spent: shallow copy
    out = []
    for item in items:
        if isinstance(item, list):
            out.extend(flatten_nested(item, depth - 1))
        else:
            out.append(item)
    return out
